using System.Numerics;
using System.Runtime.InteropServices;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for high throughput on large spans.
    /// </summary>
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (!Vector.IsHardwareAccelerated || values.Length < Vector<float>.Count)
            return FindMinMaxScalar(values);

        ReadOnlySpan<Vector<float>> vectors = MemoryMarshal.Cast<float, Vector<float>>(values);

        Vector<float> vMin = vectors[0];
        Vector<float> vMax = vectors[0];

        for (int i = 1; i < vectors.Length; i++)
        {
            vMin = Vector.Min(vMin, vectors[i]);
            vMax = Vector.Max(vMax, vectors[i]);
        }

        float min = vMin[0];
        float max = vMax[0];
        for (int i = 1; i < Vector<float>.Count; i++)
        {
            if (vMin[i] < min) min = vMin[i];
            if (vMax[i] > max) max = vMax[i];
        }

        // Handle remaining elements not covered by full vectors
        int tailStart = vectors.Length * Vector<float>.Count;
        for (int i = tailStart; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }

        return (min, max);
    }

    private static (float Min, float Max) FindMinMaxScalar(ReadOnlySpan<float> values)
    {
        float min = values[0];
        float max = values[0];
        for (int i = 1; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }
        return (min, max);
    }
}

